import gurobipy as gp
from gurobipy import GRB

# Create model
model = gp.Model()

# Sets and Parameters
N = 4
cities = [1, 2, 3, 4]
start = 1

# Cost matrix
c = {
    (1, 1): 0, (1, 2): 10, (1, 3): 20, (1, 4): 12,
    (2, 1): 10, (2, 2): 0, (2, 3): 5,  (2, 4): 10,
    (3, 1): 20, (3, 2): 5,  (3, 3): 0, (3, 4): 8,
    (4, 1): 15, (4, 2): 12, (4, 3): 8,  (4, 4): 0
}

# Decision Variables
# x[i][j] = 1 if route travels from city i to city j
x = {}
# u[i] = position of city i in the tour
u = {}

for i in cities:
    for j in cities:
        if i != j:
            x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")
    u[i] = model.addVar(vtype=GRB.CONTINUOUS, name=f"u_{i}")

# Objective
model.setObjective(gp.quicksum(c[i, j] * x[(i, j)] for i in cities for j in cities if i != j), GRB.MINIMIZE)

# Constraints
# Out-degree constraint
for i in cities:
    model.addConstr(gp.quicksum(x[(i, j)] for j in cities if i != j) == 1, name=f"out_{i}")

# In-degree constraint
for j in cities:
    model.addConstr(gp.quicksum(x[(i, j)] for i in cities if i != j) == 1, name=f"in_{j}")

# Subtour elimination (Miller-Tucker-Zemlin constraints)
# u_i - u_j + N * x_ij <= N - 1
for i in cities:
    for j in cities:
        if i != j:
            model.addConstr(u[i] - u[j] + N * x[(i, j)] <= N - 1, name=f"mtz_{i}_{j}")

# Position bounds for auxiliary variables
model.addConstr(u[start] == 1, name=f"u_start")
for i in cities:
    if i != start:
        model.addConstr(u[i] >= 2, name=f"u_lb_{i}")
        model.addConstr(u[i] <= N, name=f"u_ub_{i}")

# Optimize
model.optimize()

# Output results
if model.status == GRB.OPTIMAL:
    print(f"Minimum total distance: {model.objVal}")
    # Extract route sequence
    route = []
    current = start
    for _ in range(N):
        for next_city in cities:
            if next_city != current:
                if x[(current, next_city)].X > 0.5:
                    route.append(next_city)
                    current = next_city
                    break
    print(f"Route: {start} -> {route}")
    print(f"FINAL_OBJECTIVE={model.objVal}")

