# Objective
obj_expr = gp.quicksum(c[(i, k)] * x[(i, k)] for i in I for k in K)
obj_expr += gp.quicksum(cp[(k, j)] * y[(k, j)] for k in K for j in J)
obj_expr += gp.quicksum(f[k] * z[k] for k in K)
